import {aiConnectorMarkup,mountAiConnector} from './ai-connector.js';
import {documentsMarkup,mountDocuments} from './cell-documents.js';
import {comparisonPreview,mountComparisonPreview} from './comparison-preview.js';
import {skyMarkup,mountSky} from './sky.js';
import {MIRA_CELL} from './sky-model.js';
import { STATUS, MIRA, regionBounds, cellBounds, regionName, cellName, key, readState, sampleStatus, regionStatus, parseSelection, nextRegion } from './model.js';
import { drawAtlas } from './atlas.js';
const app = document.querySelector('#app');
let state = readState(), animation, reviewTimer, resizeTimer, reviewRun = null;
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repeats = (n,fn) => Array.from({length:n},(_,i)=>fn(i)).join('');
const real = (r,c) => r===MIRA.region && c===MIRA.cell;
const urlFor = (r=null,c=null) => '/explore/'+(r===null?'':`?region=${r}`+(c===null?'':`&cell=${c}`));
const shownStatus = (r,c) => reviewRun?.r===r && reviewRun?.c===c ? 'working' : sampleStatus(r,c,state.reviews);
const statusIcon = s => `<span class="status-icon" style="--status:${STATUS[s].color}" aria-hidden="true">${STATUS[s].icon}</span>`;
function save(){try{localStorage.setItem('sate-prototype-v1',JSON.stringify(state));return true;}catch{toast('Browser storage is unavailable. Changes last for this visit.');return false;}}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function header(path){return `<header class="site-header"><a class="brand" href="/" aria-label="SATE home"><span class="brand-mark" aria-hidden="true">${repeats(9,()=>'<i></i>')}</span>SATE</a><nav class="header-nav" aria-label="Main navigation">${[['/explore/','Explore / Manual'],['/saved-cells/','Saved cells'],['/contribute/','Contribute'],['/about/','About']].map(([p,n])=>`<a href="${p}" ${path===p?'class="active" aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="header-end"><button class="theme-switch" type="button" role="switch" aria-label="Dark mode" aria-checked="${document.documentElement.dataset.theme==='dark'}" title="Toggle dark mode"><svg class="theme-moon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.5 14.5A8.5 8.5 0 0 1 9.5 3.5a8.5 8.5 0 1 0 11 11Z"/></svg><span class="theme-switch-track" aria-hidden="true"><i></i></span></button></div></header>`;}
function footer(){return `<footer class="site-footer"><a class="footer-brand" href="/">SATE</a><span>SATE helps you explore telescope images and compare observations of the same sky region.</span><div class="footer-links"><a href="/about/">About, data &amp; sources</a></div></footer>`;}
function navigate(url,{replace=false}={}){clearInterval(animation);animation=null;(replace?history.replaceState:history.pushState).call(history,{},'',url);render();window.scrollTo(0,0);}
function landing(){return `<main id="main"><section class="hero hero-photo"><img class="hero-background" src="/assets/carina-nebula-hero.png" alt="" width="1280" height="741" fetchpriority="high"><div class="hero-inner shell"><div class="hero-copy"><h1>Help find objects<br>in space</h1><p>Explore telescope images, select a region of the sky, and compare observations to see how objects change over time and help find objects.</p><div class="hero-actions"><a class="button lime button-large" href="/explore/">Open sky map ${arrow}</a><a class="button outline button-large" href="/contribute/">Contribute with AI ${arrow}</a></div></div></div><a class="hero-image-credit" href="https://science.nasa.gov/asset/webb/cosmic-cliffs-in-the-carina-nebula-nircam-image/" target="_blank" rel="noreferrer">Webb · Cosmic Cliffs<br><span>Image: NASA, ESA, CSA, STScI ↗</span></a></section><div class="shell"><div class="hero-bottom"><span><i class="dot"></i> PUBLIC TELESCOPE DATA</span><span>EXPLORE REGIONS. COMPARE OBSERVATIONS.</span><a href="/about/">ABOUT THIS PROTOTYPE ↗</a></div></div>${comparisonPreview()}<section class="shell participation"><div><h2 class="section-title">Help analyse<br>telescope images.</h2><p class="section-copy">Explore real observations through the sky map, then learn how AI analysis and computing contributions could help investigate changes.</p><a class="text-link" href="/contribute/">Find your way to help ${arrow}</a></div><div class="participation-list"><a href="/contribute/" class="contribution-line contribution-photo ai-photo"><img class="contribution-image" src="/assets/spherex-orbit-card.jpg" alt="" width="1920" height="1080" loading="lazy"><div><h3>Bring your AI</h3><p>Give an assistant a small investigation. Compare images, check sources, bring back the evidence.</p></div>${arrow}</a><a href="/explore/" class="contribution-line contribution-photo observation-action"><img class="contribution-image" src="/assets/spherex-observation-card.jpg" alt="" width="1024" height="575" loading="lazy"><div><h3>See real observations manually through sky map</h3><p>Explore telescope images, select a sky region and view it at different wavelengths.</p></div>${arrow}</a><a class="contribution-credits" href="/about/">Images: NASA/JPL-Caltech</a></div></section></main>${footer()}`;}
function contribute(){return aiConnectorMarkup();}
function about(){return `<main id="main" class="about-page">
<header class="about-heading"><h1>About SATE</h1><p>Compare real infrared observations of the same sky region across dates and wavelengths.</p><div class="about-links"><a href="/explore/">Explore the sky →</a><a href="https://github.com/Abaqueque/SATE" target="_blank" rel="noreferrer">Source code ↗</a></div></header>
<section><h2>The challenge</h2><p>SATE responds to <a href="https://www.spaceappschallenge.org/2026/challenges/planet-x-and-spherex/" target="_blank" rel="noreferrer">Planet X and SPHEREx</a>, a NASA Space Apps Challenge 2026 problem: make changes in the infrared sky easier for anyone to explore.</p><p>Finding and aligning telescope files takes specialist tools. SATE brings the map, dated observations and source records into one browser workflow for students and citizen scientists.</p></section>
<section><h2>What you can do</h2><p>Find an object or choose a sky region. Select a wavelength, move through observation dates, or compare two views. Add colour layers, overlay known objects, inspect possible motion and save a cell with notes, image previews, dates and source files.</p><p>The all-sky map combines observations across time. The observation viewer shows individual dated exposures. Saved cells stay in your browser and can be exported as JSON.</p></section>
<section><h2>Data and method</h2><p>The atlas uses the SPHEREx DR1 all-sky HiPS cube in 102 wavelength channels. Dated images come from DR1 and QR3 FITS products served by NASA/IPAC IRSA. CDS Sesame resolves object names.</p><p>Images are aligned to a fixed sky grid using their coordinate calibration. At least 80% of the full field must contain finite image data before an exposure enters the timeline. Quality and wavelength masks can hide more pixels. Original FITS files remain available.</p><p>Coordinate handling is checked independently with Python and Astropy. Display contrast, colour and noise adjustments help inspection; they are not calibrated brightness measurements.</p></section>
<section id="known-objects"><h2>Known objects</h2><p>Turn on Known objects beside Two viewers to identify catalogued sources in each dated image. Blue circles show SIMBAD objects, with positions advanced from J2000 using measured proper motion where available. Objects without motion measurements stay at their catalogue position. Annual parallax and perspective acceleration are not included.</p><p>Amber diamonds show NASA/JPL predictions for asteroids and comets at the exposure midpoint recorded in the original FITS file. The search uses JPL’s second-pass orbit integration and includes objects with predicted visual magnitude V ≤ 22. Predictions currently use Earth’s centre, not the spacecraft position; nearby objects can therefore be offset. Names, coordinates and source links are available by selecting a marker.</p><p>Each viewer uses its own observation date. Markers follow image zoom and framing, and are hidden for combined exposures, added wavelength layers and blended comparisons, which do not have one observation time. SIMBAD results are limited to 1,500 nearby records; a partial result is labelled. These services are not a complete inventory of every detectable infrared source. An unmarked source is not evidence of a discovery.</p></section>
<section><h2>What a result means</h2><p>A moving or changing patch is a lead to investigate. Detector defects, missing samples, different wavelengths and different image sharpness can imitate change. Motion tracking is approximate. “Estimate missing pixels” uses nearby spectral samples for display only, with a label on the image. It cannot recover an unmeasured value or confirm a detection. SATE has not confirmed a new planet or asteroid, and an empty view does not establish that a region contains none.</p><p>The Contribute page lets you select real sky regions and queue them in order for an AI assistant. Connector execution is currently a preview; it does not use an AI account or allowance or generate scientific reviews. Live AI connections and shared computing remain planned features. Review shading illustrates the review workflow; it does not record completed scientific searches.</p></section>
<section><h2>Tools and AI use</h2><p>Built with JavaScript, HTML, CSS and Canvas, Aladin Lite, HEALPix, and Node.js on Vercel. OpenAI Codex and Anthropic Claude assisted with code, testing and wording. Telescope observations are measured SPHEREx data, not generated imagery.</p></section>
<section id="sources"><h2>Sources and credits</h2><ul>
<li><a href="https://irsa.ipac.caltech.edu/Missions/spherex.html" target="_blank" rel="noreferrer">SPHEREx archive · NASA/IPAC IRSA</a> and <a href="https://caltech-ipac.github.io/spherex-archive-documentation/spherex-data-products/" target="_blank" rel="noreferrer">data-product documentation</a></li>
<li><a href="https://aladin.cds.unistra.fr/AladinLite/" target="_blank" rel="noreferrer">Aladin Lite · CDS</a>, <a href="https://cds.unistra.fr/cgi-bin/Sesame" target="_blank" rel="noreferrer">Sesame name resolver</a> and <a href="https://healpix.sourceforge.io/" target="_blank" rel="noreferrer">HEALPix</a></li>
<li><a href="https://simbad.cds.unistra.fr/simbad/" target="_blank" rel="noreferrer">SIMBAD astronomical database · CDS</a> and <a href="https://simbad.cds.unistra.fr/Pages/guide/sim-id.htx" target="_blank" rel="noreferrer">coordinate and proper-motion conventions</a></li>
<li><a href="https://ssd-api.jpl.nasa.gov/doc/sb_ident.html" target="_blank" rel="noreferrer">NASA/JPL Small-Body Identification API</a> · asteroid and comet predictions</li>
<li id="image-credits"><a href="https://science.nasa.gov/asset/webb/cosmic-cliffs-in-the-carina-nebula-nircam-image/" target="_blank" rel="noreferrer">Homepage: Webb’s Cosmic Cliffs</a> · NASA, ESA, CSA, STScI</li>
<li><a href="https://science.nasa.gov/photojournal/spherex-in-orbit-artists-concept/" target="_blank" rel="noreferrer">SPHEREx spacecraft illustration</a> and <a href="https://www.nasa.gov/missions/spherex/nasas-spherex-space-telescope-begins-capturing-entire-sky/" target="_blank" rel="noreferrer">infrared observation image</a> · NASA/JPL-Caltech</li>
<li><a href="/assets/LICENSE">D3-Celestial · Olaf Frohn and contributors, BSD 3-Clause</a></li>
<li><a href="https://www.spaceappschallenge.org/resources/judging-awards-guide/" target="_blank" rel="noreferrer">2026 judging criteria</a> and <a href="https://www.spaceappschallenge.org/resources/project-submission-guide/" target="_blank" rel="noreferrer">project submission guide</a></li>
</ul></section></main>${footer()}`;}
function paint(){const hero=document.querySelector('#hero-canvas');if(hero)drawAtlas(hero,{polar:true});const sky=document.querySelector('#sky-canvas');if(sky){const{region}=parseSelection(location.search);drawAtlas(sky,region===null?{}:{bounds:regionBounds(region)});}}
let skyCleanup,renderToken=0;
function render(){const token=++renderToken;skyCleanup?.();skyCleanup=null;let path=location.pathname.replace(/\/+$/,'')+'/';if(path==='//')path='/';if(path==='/explore/'&&(new URLSearchParams(location.search).has('assign')||new URLSearchParams(location.search).has('region'))){history.replaceState({},'','/explore/?hpx='+MIRA_CELL+'&order=9');}document.body.classList.toggle('explorer-page',path==='/explore/');const pages={'/':landing,'/explore/':skyMarkup,'/contribute/':contribute,'/about/':about,'/saved-cells/':documentsMarkup};app.innerHTML=header(path)+(pages[path]?pages[path]():`<main id="main" class="not-found"><h1>A little off course.</h1><a class="button" href="/">Return home ${arrow}</a></main>`);document.title=({'/':'Explore and compare space observations','/explore/':'Sky atlas','/contribute/':'Contribute','/about/':'About SATE','/saved-cells/':'Saved cells'}[path]||'Not found')+' — SATE';paint();if(path==='/')skyCleanup=mountComparisonPreview();if(path==='/explore/')mountSky().then(clean=>{if(token===renderToken)skyCleanup=clean;else clean?.();});if(path==='/saved-cells/')skyCleanup=mountDocuments();if(path==='/contribute/')skyCleanup=mountAiConnector();}
app.addEventListener('click',async e=>{const link=e.target.closest('a');if(link){if(link.hasAttribute('download')||link.target||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const u=new URL(link.href);if(u.origin===location.origin&&!u.pathname.startsWith('/assets/')){if(location.pathname.startsWith('/explore')||u.pathname.startsWith('/explore'))return;e.preventDefault();navigate(u.pathname+u.search+u.hash);}return;}const button=e.target.closest('button');if(button?.classList.contains('theme-switch')){window.sateTheme.toggle();return;}if(!button||button.closest('[data-sky]'))return;if(button.dataset.selectRegion!==undefined){navigate('/explore/?inspect='+Number(button.dataset.selectRegion));return;}if(button.dataset.region!==undefined){navigate(urlFor(Number(button.dataset.region)));return;}if(button.dataset.cell!==undefined){const{region}=parseSelection(location.search);navigate(urlFor(region,Number(button.dataset.cell)));return;}switch(button.dataset.action){case'all':navigate(urlFor());break;case'example-cell':navigate('/explore/?inspect='+MIRA.region);break;case'auto':{const n=nextRegion(state.reviews);if(n)navigate(urlFor(n.region,n.cell));else toast('All demo cells have been assigned. Reset the demo to start again.');break;}case'cancel':clearInterval(reviewTimer);reviewRun=null;render();break;case'copy':try{await navigator.clipboard.writeText(location.href);toast('Cell link copied.');}catch{toast('Copy the cell URL from your address bar.');}break;case'reset':localStorage.removeItem('sate-healpix-reviews-v1');clearInterval(reviewTimer);reviewRun=null;state={reviews:{},preferences:{ai:true,compute:false,batch:'5',power:'light'}};save();toast('Demo activity reset.');break;}});
app.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='coordinate-form'){const ra=Number(f.get('ra')),dec=Number(f.get('dec'));if(!Number.isFinite(ra)||ra<0||ra>=360||!Number.isFinite(dec)||dec< -90||dec>90){document.querySelector('#coord-error').textContent='Use RA 0–360° and Dec −90–90°.';return;}const col=Math.min(11,Math.floor((360-ra)/30)),row=Math.min(5,Math.floor((90-dec)/30)),r=row*12+col,b=regionBounds(r),c=Math.min(2,Math.floor((b.north-dec)/10))*3+Math.min(2,Math.floor((b.west-ra)/10));navigate(urlFor(r,c));}});
app.addEventListener('keydown',e=>{const b=e.target.closest('.map-cell,.nine-grid button');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const list=[...b.parentNode.children],cols=b.parentNode.classList.contains('subgrid')||b.parentNode.classList.contains('nine-grid')?3:12,index=list.indexOf(b),move={ArrowLeft:-1,ArrowRight:1,ArrowUp:-cols,ArrowDown:cols}[e.key];e.preventDefault();const next=list[Math.max(0,Math.min(list.length-1,index+move))];b.tabIndex=-1;next.tabIndex=0;next.focus();});
window.addEventListener('popstate',()=>{clearInterval(animation);animation=null;render();});window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(paint,120);});render();
